const token=localStorage.getItem('owar-admin-token')||prompt('Enter the admin token'); if(token)localStorage.setItem('owar-admin-token',token); const auth={Authorization:`Bearer ${token}`}; let data;
const option=(id,selected)=>`<option value="${id}" ${String(id)===String(selected)?'selected':''}>${data.events.find(e=>String(e.id)===String(id))?.name||id}</option>`;
const eventSelect=selected=>`<select class="event">${data.events.map(e=>option(e.id,selected)).join('')}</select>`;
function stageRow(s={}){return `<div class="form-row stage-row"><input class="label" placeholder="Stage label" value="${s.label||''}">${eventSelect(s.event_id)}<input class="phase" placeholder="Phase e.g. Heat" value="${s.phase||''}"><button class="remove">Remove</button></div>`}
function ruleRow(r={}){return `<div class="form-row rule-row">${eventSelect(r.source_event_id)}<input class="position" type="number" min="1" value="${r.position||1}" aria-label="Source position">${eventSelect(r.target_event_id)}<input class="slot" type="number" min="1" value="${r.target_slot||1}" aria-label="Destination slot"><button class="remove">Remove</button></div>`}
function bind(){document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>b.parentElement.remove())}
async function load(){const r=await fetch('/api/admin/tournament',{headers:auth}); data=await r.json(); if(!r.ok)throw Error(data.error); document.querySelector('#stage-list').innerHTML=data.stages.map(stageRow).join(''); document.querySelector('#rule-list').innerHTML=data.rules.map(ruleRow).join(''); bind()}
function stages(){return [...document.querySelectorAll('.stage-row')].map(r=>({event_id:r.querySelector('.event').value,label:r.querySelector('.label').value,phase:r.querySelector('.phase').value}))}
function rules(){return [...document.querySelectorAll('.rule-row')].map(r=>({source_event_id:r.querySelectorAll('.event')[0].value,position:r.querySelector('.position').value,target_event_id:r.querySelectorAll('.event')[1].value,target_slot:r.querySelector('.slot').value}))}
function renderPreset(s,r){document.querySelector('#stage-list').innerHTML=s.map(stageRow).join('');document.querySelector('#rule-list').innerHTML=r.map(ruleRow).join('');bind()}
document.querySelector('#add-stage').onclick=()=>{document.querySelector('#stage-list').insertAdjacentHTML('beforeend',stageRow());bind()}; document.querySelector('#add-rule').onclick=()=>{document.querySelector('#rule-list').insertAdjacentHTML('beforeend',ruleRow());bind()}; document.querySelector('#save').onclick=async()=>{const r=await fetch('/api/admin/tournament',{method:'POST',headers:{...auth,'Content-Type':'application/json'},body:JSON.stringify({stages:stages(),rules:rules()})}); const out=await r.json(); document.querySelector('#message').textContent=r.ok?'Saved. The event tree has been refreshed.':out.error||'Could not save.'}; load().catch(e=>document.querySelector('#message').textContent=e.message);
document.querySelector('#top32').onclick=()=>{if(data.events.length<15){document.querySelector('#message').textContent='Import at least 15 race events first.';return}const e=data.events.map(x=>x.id),s=[...e.slice(0,8).map((id,i)=>({event_id:id,label:`Heat ${i+1}`,phase:'Heats'})),...e.slice(8,12).map((id,i)=>({event_id:id,label:`Quarter-final ${i+1}`,phase:'Quarter-finals'})),...e.slice(12,14).map((id,i)=>({event_id:id,label:`Semi-final ${i+1}`,phase:'Semi-finals'})),{event_id:e[14],label:'Final',phase:'Final'}],r=[],add=(a,p,b,slot)=>r.push({source_event_id:e[a],position:p,target_event_id:e[b],target_slot:slot});[[0,1,8,1],[7,1,8,2],[3,2,8,3],[4,2,8,4],[1,1,9,1],[6,1,9,2],[2,2,9,3],[5,2,9,4],[2,1,10,1],[5,1,10,2],[1,2,10,3],[6,2,10,4],[3,1,11,1],[4,1,11,2],[0,2,11,3],[7,2,11,4],[8,1,12,1],[9,2,12,2],[11,1,12,3],[11,2,12,4],[9,1,13,1],[10,1,13,2],[10,2,13,3],[8,2,13,4],[12,1,14,1],[13,1,14,2],[12,2,14,3],[13,2,14,4]].forEach(x=>add(...x));renderPreset(s,r);document.querySelector('#message').textContent='Pattern loaded. Confirm event order, then save.'};
